type ProductScene = "inbox" | "crm" | "automation" | "ai" | "tracking";

const PRODUCT_SCENES: Array<{ key: ProductScene; label: string; eyebrow: string; title: string; text: string; icon: typeof Inbox }> = [
  { key: "inbox", label: "Inbox", eyebrow: "Atendimento com contexto", title: "A conversa e o contexto comercial ocupam a mesma tela.", text: "O atendente vê origem, etapa, responsável, produto, tags, campos, histórico e atividades sem abandonar a conversa.", icon: Inbox },
  { key: "crm", label: "CRM", eyebrow: "Funil de vendas", title: "O cartão do lead é só a superfície do processo.", text: "Por trás dele existem valores, tarefas, produtos, responsáveis, automações por etapa e toda a continuidade comercial.", icon: Users },
  { key: "automation", label: "SalesBots", eyebrow: "Builder visual", title: "A automação é desenhada como um fluxo executável.", text: "Mensagens, pausas, condições, IA, CRM, integrações e encerramento formam caminhos claros que podem ser testados antes de entrar em produção.", icon: Zap },
  { key: "ai", label: "Agentes IA", eyebrow: "Prompt ou objetivos", title: "A IA recebe contexto, objetivo, regras e saídas possíveis.", text: "Você escolhe entre prompt aberto ou uma árvore de objetivos, adiciona fontes, ações, condições e define exatamente onde o agente deve chegar.", icon: Bot },
  { key: "tracking", label: "Tracking", eyebrow: "Tracking & Analytics", title: "O módulo acompanha instalação, eventos, fontes e conversões.", text: "Pixel, UTMs, eventos customizados, diagnóstico e logs deixam a jornada auditável do primeiro acesso ao objetivo final.", icon: Activity },
];

const FAQ = [
  { q: "A MKTOn é apenas um CRM?", a: "Não. O CRM é uma parte da plataforma. A MKTOn reúne atendimento, automações, SalesBots, agentes IA, tracking, gestor de tráfego, social media, fluxo de trabalho, formulários, produtos, arquivos e outros recursos operacionais." },
  { q: "A IA consegue fazer follow-up?", a: "Sim. Agentes podem trabalhar com objetivos, regras e fontes de conhecimento para atender, qualificar, reaquecer, acompanhar leads, gerar tarefas e encaminhar o atendimento para uma pessoa quando necessário." },
  { q: "Consigo acompanhar campanhas e conversões?", a: "O Tracking possui pixel MKTOn, UTMs, eventos, fontes, conversões e diagnóstico. O Gestor de Tráfego aproxima campanhas, criativos e indicadores da leitura comercial da operação." },
  { q: "A MKTOn também ajuda na produção de conteúdo?", a: "Sim. O módulo de Social Media reúne calendário, ideias, contexto de marca, criação, campanhas e apoio de IA para organizar o processo de conteúdo." },
  { q: "Existe período de teste?", a: "Sim. Você pode criar uma conta e explorar a MKTOn por 20 dias para entender como os módulos se encaixam na sua operação." },
];

