function DarkMetric({label,value}:{label:string;value:string}){return <div className="rounded-xl border border-white/10 bg-white/[.04] p-3 sm:rounded-2xl sm:p-4"><div className="text-[7px] font-bold uppercase tracking-widest text-slate-500 sm:text-[8px] sm:tracking-widest">{label}</div><div className="mt-1.5 text-lg font-bold text-white sm:mt-2 sm:text-2xl">{value}</div></div>}
function DarkAiPanel({title,text,items}:{title:string;text:string;items:string[]}){return <div className="rounded-2xl border border-blue-400/20 bg-blue-500/[.08] p-4 sm:p-5"><div className="flex items-center gap-2 text-[10px] font-bold text-blue-300"><Sparkles className="h-4 w-4"/>{title}</div><p className="mt-3 text-xs font-bold leading-5 text-white sm:mt-4 sm:text-sm sm:leading-6">{text}</p><div className="mt-4 space-y-2 sm:mt-5">{items.map(i=><div key={i} className="flex items-center gap-2 text-[9px] leading-4 text-slate-300"><Check className="h-3 w-3 shrink-0 text-emerald-400"/>{i}</div>)}</div></div>}
function SocialCalendar(){return <div className="overflow-x-auto pb-2"><div className="flex min-w-[760px] gap-3 md:grid md:min-w-0 md:grid-cols-7">{["SEG","TER","QUA","QUI","SEX","SÁB","DOM"].map((day,i)=><div key={day} className="min-h-[160px] w-[100px] shrink-0 rounded-2xl border border-slate-200 bg-[#f8fafc] p-3 md:min-h-[180px] md:w-auto"><div className="text-[9px] font-bold text-slate-400">{day}</div>{i<5&&<div className={`mt-6 rounded-xl border p-3 md:mt-7 ${i===2?"border-blue-200 bg-blue-50":"border-slate-200 bg-white"}`}><div className="text-[9px] font-bold leading-4 text-slate-800">{["Carrossel educativo","Vídeo produto","Case operacional","Bastidor","Oferta trial"][i]}</div><div className="mt-2 text-[8px] text-slate-400">{10+i}:00 · Instagram</div></div>}</div>)}</div></div>}
