function MiniFeature({title,text}:{title:string;text:string}){return <div className="rounded-2xl border border-slate-200 bg-white p-4 text-left shadow-sm"><div className="text-xs font-bold text-slate-900 sm:text-sm">{title}</div><p className="mt-1.5 text-[11px] leading-5 text-slate-500 sm:mt-2 sm:text-xs sm:leading-6">{text}</p></div>}
